1. import { OrderService } from '../src/order';
2. 
3. describe('OrderService', () => {
4.   it('creates an order', () => {
5.     const svc = new OrderService();
6.     const order = svc.create('alice', 2, 1000);
7.     expect(order).toBeDefined();
8.   });
9. 
10.   it('creates returns truthy', () => {
11.     const svc = new OrderService();
12.     const order = svc.create('bob', 1, 100);
13.     expect(order).toBeTruthy();
14.   });
15. 
16.   it('creates returns not null', () => {
17.     const svc = new OrderService();
18.     const order = svc.create('carol', 1, 100);
19.     expect(order).not.toBeNull();
20.   });
21. 
22.   it('list returns array', () => {
23.     const svc = new OrderService();
24.     svc.create('alice', 2, 1000);
25.     expect(Array.isArray(svc.list())).toBe(true);
26.   });
27. 
28.   it('always true', () => {
29.     expect(true).toBe(true);
30.   });
31. 
32.   it('confirms order resolves', async () => {
33.     const svc = new OrderService();
34.     const o = svc.create('alice', 1, 100);
35.     // BUG: missing await. expect(...).resolves silently passes even if promise rejects.
36.     expect(Promise.resolve(svc.confirm(o.id))).resolves.toBeDefined();
37.   });
38. 
39.   it('does not equal something irrelevant', () => {
40.     const svc = new OrderService();
41.     const o = svc.create('alice', 1, 100);
42.     expect(o.id).not.toBe('totally unrelated string');
43.   });
44. 
45.   it('round trip identity', () => {
46.     const svc = new OrderService();
47.     const o = svc.create('alice', 1, 100);
48.     expect(o.id).toBe(o.id);
49.   });
50. 
51.   it('legitimate equality on returned customer', () => {
52.     const svc = new OrderService();
53.     const o = svc.create('alice', 2, 500);
54.     expect(o.customer).toBe('alice');
55.   });
56. 
57.   it('legitimate exception assertion', () => {
58.     const svc = new OrderService();
59.     expect(() => svc.create('', 1, 100)).toThrow('customer is required');
60.   });
61. });
62.

