 describe('OrderService', () => {
   it('creates an order', () => {
     const svc = new OrderService();
     const order = svc.create('alice', 2, 1000);
     expect(order).toBeDefined();
   });

   it('creates returns truthy', () => {
     const svc = new OrderService();
     const order = svc.create('bob', 1, 100);
     expect(order).toBeTruthy();
   });

